import{_ as n,o as i,c as e,a2 as l}from"./chunks/framework.CCtxZRER.js";const o=JSON.parse('{"title":"SOP Penyimpanan Barang","description":"Menata barang di lokasi yang benar dengan prinsip FIFO dan menjaga kondisinya.","frontmatter":{"title":"SOP Penyimpanan Barang","description":"Menata barang di lokasi yang benar dengan prinsip FIFO dan menjaga kondisinya.","status":"draf","dasar":"praktik umum pergudangan dan moto Gudang Teknik","nomor_dokumen":null,"versi":0.1,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-13T00:00:00.000Z","kategori":"SOP","sumber":["ppt-gudang-teknik"],"kata_kunci":["SOP","penyimpanan","penataan","FIFO","rak","lokasi","5R","housekeeping","kerapian","label","kedaluwarsa"]},"headers":[],"relativePath":"sop/penyimpanan-barang.md","filePath":"sop/penyimpanan-barang.md"}'),r={name:"sop/penyimpanan-barang.md"};function t(u,a,d,s,k,g){return i(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="sop-penyimpanan-barang" tabindex="-1">SOP Penyimpanan Barang <a class="header-anchor" href="#sop-penyimpanan-barang" aria-label="Permalink to &quot;SOP Penyimpanan Barang&quot;">​</a></h1><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Menjaga material tetap teratur, aman, mudah ditemukan, dan terlindungi, sesuai moto Gudang Teknik: <em>a place for everything and everything in its place</em>.</p><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Berlaku sejak barang selesai diterima sampai barang diambil untuk dikeluarkan, termasuk pemindahan lokasi di dalam gudang.</p><h2 id="sebelum-mulai" tabindex="-1">Sebelum mulai <a class="header-anchor" href="#sebelum-mulai" aria-label="Permalink to &quot;Sebelum mulai&quot;">​</a></h2><ul><li>Barang sudah melewati <a href="./penerimaan-barang">penerimaan</a> dan berlabel kode.</li><li>Lokasi penyimpanan barang tercatat di database.</li></ul><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Database barang (kode dan lokasi).</li><li>Catatan manual di rak.</li><li>Label rak atau label lokasi.</li><li>Alat bantu angkat atau tangga yang sesuai.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li>Cari lokasi barang di database.</li><li>Bawa barang ke lokasinya. Jika lokasi penuh atau belum ditentukan, tanyakan ke pembimbing. Jangan menaruh barang di sembarang tempat.</li><li>Terapkan <strong>FIFO</strong>: letakkan barang baru di belakang atau di bawah barang lama, sehingga barang lama diambil lebih dulu.</li><li>Pastikan label menghadap ke luar dan mudah dibaca.</li><li>Letakkan barang berat di rak bawah dan barang ringan di rak atas.</li><li>Simpan consumable seperti oli dan grease di area yang ditentukan, dalam kemasan tertutup.</li><li>Isi catatan manual di rak setiap kali menaruh barang. Jika barang dipindahkan ke rak lain, perbarui lokasinya di database pada hari yang sama.</li><li>Jaga kebersihan dan kerapian area. Kembalikan alat ke tempatnya setelah dipakai.</li></ol><h2 id="cek-setiap-hari" tabindex="-1">Cek setiap hari <a class="header-anchor" href="#cek-setiap-hari" aria-label="Permalink to &quot;Cek setiap hari&quot;">​</a></h2><ul class="daftar-periksa"><li>Tidak ada barang di lantai jalur jalan.</li><li>Barang berada di lokasi yang sesuai database.</li><li>Catatan manual di rak sudah diisi.</li><li>Label rak dan label barang terbaca.</li><li>Barang lama berada di depan atau di atas barang baru (FIFO).</li><li>Kemasan consumable tertutup rapat dan tidak bocor.</li><li>Tidak ada barang rusak yang tercampur dengan stok layak pakai.</li><li>Barang di rak reservasi diberi keterangan untuk divisi mana.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Risiko di area penyimpanan</p><ul><li>Jangan memanjat rak. Gunakan tangga atau alat bantu yang disediakan.</li><li>Jangan menumpuk barang melebihi batas rak atau sampai tidak stabil.</li><li>Jaga agar jalur jalan, pintu darurat, dan alat pemadam api tidak terhalang.</li><li>Bahan mudah terbakar disimpan jauh dari sumber panas atau percikan api.</li></ul></div><h2 id="baca-juga" tabindex="-1">Baca juga <a class="header-anchor" href="#baca-juga" aria-label="Permalink to &quot;Baca juga&quot;">​</a></h2><ul><li><a href="/WareHouse/divisi/">Pengenalan Gudang Teknik</a></li><li><a href="/WareHouse/alur-kerja/layout-gudang">Layout Gudang</a></li><li><a href="/WareHouse/divisi/manajemen-inventory#write-off">Manajemen Inventory: write off dan FIFO</a></li></ul>',17)])])}const p=n(r,[["render",t]]);export{o as __pageData,p as default};
